using OfficeIMO.Drawing;
using Xunit;

namespace OfficeIMO.Tests;

public sealed class DrawingJpegGreenRoundingTests {
    // Own constant YCbCr swatches independently encoded at quality 85 and decoded
    // with libjpeg-turbo 3.1.4.1. Expected RGB values are native output samples.
    // Baseline and progressive 4:4:4/4:2:0 cover both signs of the rounding error.
    [Theory]
    [MemberData(nameof(ColorFixtures))]
    public void GreenChannelMatchesIndependentColorSamples(string name, string encoded, byte[] expectedRgb) {
        byte[] jpeg = Convert.FromBase64String(encoded);
        var expected = new byte[16 * 16 * 4];
        for (int index = 0; index < 16 * 16; index++) {
            expected[index * 4] = expectedRgb[0];
            expected[index * 4 + 1] = expectedRgb[1];
            expected[index * 4 + 2] = expectedRgb[2];
            expected[index * 4 + 3] = 255;
        }
        foreach (bool smooth in new[] { false, true }) {
            var actual = OfficeJpegCodec.Decode(jpeg, new OfficeJpegDecodeOptions(highQualityChroma: smooth));
            Assert.Equal(16, actual.Width);
            Assert.Equal(16, actual.Height);
            Assert.True(expected.SequenceEqual(actual.GetPixels()), $"Unexpected RGB samples for {name}; smooth={smooth}.");
        }
    }

    public static IEnumerable<object[]> ColorFixtures() {
        yield return new object[] { "positive-444",
            "", new byte[] { 113, 131, 151 } };
        yield return new object[] { "positive-420",
            "", new byte[] { 113, 131, 151 } };
        yield return new object[] { "negative-444",
            "", new byte[] { 143, 125, 105 } };
        yield return new object[] { "negative-420",
            "", new byte[] { 143, 125, 105 } };
    }
}
